import { mergeContact } from "./merge.ts";
import { normalizeEmail } from "./normalize.ts";
import type { Contact } from "./types.ts";

/**
 * Adds the incoming contacts to the existing ones. A contact whose email is already present
 * is merged into that entry; everything else is appended in the order it arrives.
 */
export function mergeContacts(existing: Contact[], incoming: Contact[]): Contact[] {
  const result = [...existing];
  const indexByEmail = new Map<string, number>();
  result.forEach((entry, index) => remember(indexByEmail, entry, index));
  for (const contact of incoming) {
    const index = indexByEmail.get(normalizeEmail(contact.email));
    if (index === undefined) {
      remember(indexByEmail, contact, result.push(contact) - 1);
    } else {
      result[index] = mergeContact(result[index], contact);
    }
  }
  return result;
}

/** Records where an email first appears; later entries with the same email never receive merges. */
function remember(indexByEmail: Map<string, number>, contact: Contact, index: number): void {
  const key = normalizeEmail(contact.email);
  if (!indexByEmail.has(key)) indexByEmail.set(key, index);
}
